usage.code:
// nextflow.config
process {
    errorStrategy = 'retry'        // 失败自动重试，适合集群的偶发失败
    maxRetries = 2
    maxForks = 20                  // 同时运行的任务上限
}

profiles {
    local {
        process.executor = 'local'
        process.cpus = 4
    }
    slurm {
        process.executor = 'slurm'
        process.queue = 'normal'
        process.clusterOptions = '--account=myproject'
    }
    docker {
        docker.enabled = true
    }
}
